#!/bin/bash
# ============================================================================
# install_wrapup.sh -- final documentation pass for the reasoning-trace track.
#
# Corrects the write-ups against the 994-document results, adds the leakage
# audit, marks the superseded documents, and adds a track entry point.
# NO pipeline code changes: the only source file touched is a docstring in
# probes/linear.py warning that its CV number is optimistic. Nothing needs
# re-running.
#
# Run from the repo root on Bender:   bash install_wrapup.sh
# Delete this script once it has run -- it is a delivery vehicle, not source.
# ============================================================================
set -euo pipefail

if [ ! -d scripts ] || [ ! -d src/probe_extraction ]; then
  echo "FATAL: run this from the NLP_Lab repo root (no scripts/ or src/ here)."
  exit 1
fi

TS=$(date +%Y%m%d-%H%M%S)
mkdir -p docs src/probe_extraction/probes

write_file() {   # write_file <path> <sha256> <<< base64
  local path="$1" want="$2" b64 got cur
  b64=$(cat)
  if [ -f "$path" ]; then
    cur=$(sha256sum "$path" | cut -d' ' -f1)
    if [ "$cur" = "$want" ]; then
      echo "  ok  $path (unchanged)"
      return 0
    fi
    cp -p "$path" "${path}.bak.${TS}"
  fi
  printf '%s' "$b64" | base64 -d > "$path"
  got=$(sha256sum "$path" | cut -d' ' -f1)
  if [ "$got" != "$want" ]; then
    echo "FATAL: checksum mismatch for $path"
    echo "  expected $want"
    echo "  got      $got"
    exit 1
  fi
  echo "  ok  $path"
}

echo "=== NEW FILES ==="
write_file 'docs/REASONING_TRACK.md' '4a8ee3893512a1cd2f8fad201a47ab35a0f8732222fc8e284acc7b56dc47e3e8' <<'B64EOF'
